settings.custom_css:
.hero_button span svg{
    font-size: 7px;


}
.hero_button span svg{
    font-size: 7px;
    animation: pulse 2s cubic-bezier(.4, 0, .6, 1) infinite;

    transform-box: fill-box;
    transform-origin: center;
}

@keyframes pulse {
    0%, 100% {
        opacity: 1;
        transform: scale(1);
    }

    50% {
        opacity: .5;
        transform: scale(1.12);
    }
}

.text-gradient
 
 {
    background: linear-gradient(120deg, #3600aa 0%, #a082ff 100%);
    color: #0000;
    -webkit-background-clip: text!important;
    background-clip: text!important;
}
